/**
 * Declaraciones de modulos para las librerias de iconos de Iconscout.
 * Necesarias porque estas librerias no incluyen tipos de TypeScript,
 * por lo que sin estas declaraciones el compilador lanzaria errores
 * al importar cualquier icono.
 */
declare module '@iconscout/react-unicons'
declare module '@iconscout/react-unicons/icons/*'
declare module '@iconscout/react-unicons-solid'
declare module '@iconscout/react-unicons-solid/icons/*'